<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ArrowUpRight, ArrowRight, Plus, Wallet, TrendingUp, ReceiptText, ArrowDownLeft, Info, Package, RefreshCw } from '@lucide/vue'
import { api, money, dateLabel, session } from '../api'
import type { Dashboard } from '../types'
const data = ref<Dashboard>(), days = ref(7), error = ref(''), loading = ref(false)
async function load() { loading.value = true; error.value = ''; try { data.value = await api<Dashboard>(`dashboard/?days=${days.value}`) } catch(e) { error.value = (e as Error).message } finally { loading.value = false } }
onMounted(load); watch(days, load)
const max = computed(() => Math.max(1, ...(data.value?.trend.flatMap(t => [Number(t.revenue), Number(t.expenses)]) || [1])))
const totalExpense = computed(() => Number(data.value?.expenses || 0))
const growth = computed(() => { if (!data.value) return '—'; const prev = Number(data.value.previous_revenue); return prev ? `${((Number(data.value.revenue) - prev) / prev * 100).toFixed(1)}% oldingi davrga` : 'Oldingi davrda tushum yo‘q' })
const tiles = computed(() => data.value ? [
  {name:'Jami tushum', value:data.value.revenue, icon:Wallet, color:'green', note:growth.value},
  {name:'Kiritilgan xarajat', value:data.value.expenses, icon:ArrowDownLeft, color:'orange', note:'To‘langan va to‘lanmagan'},
  {name:'Sof pul oqimi', value:data.value.net_cash, icon:TrendingUp, color:'blue', note:'Kirim − to‘langan chiqim'},
  {name:'To‘langan cheklar', value:data.value.paid_count, icon:ReceiptText, color:'violet', note:`${data.value.open_count} ta ochiq hisob`, count:true},
] : [])
</script>
<template><div class="page-heading"><div><span class="eyebrow">RESTORAN PULSI</span><h1>Umumiy holat<span class="heading-dot">.</span></h1><p>Salom, {{ session.user?.name }}. Restoraningizdagi muhim raqamlar shu yerda.</p></div><div class="heading-actions"><button class="button secondary icon-button" :disabled="loading" aria-label="Yangilash" @click="load"><RefreshCw :size="17"/></button><select v-model="days" aria-label="Hisobot davri"><option :value="7">Oxirgi 7 kun</option><option :value="30">Oxirgi 30 kun</option></select><RouterLink to="/pos" class="button primary"><Plus :size="17"/>Yangi buyurtma</RouterLink></div></div><p v-if="error" class="alert error" role="alert">{{ error }}</p><div v-if="!data && loading" class="empty-state">Hisobot yuklanmoqda…</div><template v-if="data"><div class="metric-grid"><article v-for="tile in tiles" :key="tile.name" class="metric-card"><div class="metric-top"><span>{{ tile.name }}</span><span class="metric-icon" :class="tile.color"><component :is="tile.icon" :size="19"/></span></div><div class="metric-value">{{ money(tile.value) }}<small>{{ tile.count ? 'ta' : 'so‘m' }}</small></div><p>{{ tile.note }}</p></article></div><div class="dashboard-grid"><section class="panel revenue-panel"><header class="panel-heading"><div><h2>Tushum va xarajatlar</h2><p>Kunlar bo‘yicha hisoblangan ko‘rsatkichlar</p></div><span class="pill subtle">{{ days }} kun</span></header><div class="chart-legend"><span><i class="green-dot"/>Tushum</span><span><i class="orange-dot"/>Xarajat</span><small>so‘m</small></div><div class="bar-chart" role="img" aria-label="Kunlik tushum va xarajatlar grafigi"><div class="chart-grid-lines"><span>{{ money(max) }}</span><span>{{ money(max / 2) }}</span><span>0</span></div><div class="bar-groups"><div v-for="point in data.trend" :key="point.date" class="bar-group" :title="`${point.date}: tushum ${money(point.revenue)}, xarajat ${money(point.expenses)}`"><div class="bars"><span class="revenue-bar" :style="{height: `${Number(point.revenue) / max * 100}%`}"/><span class="expense-bar" :style="{height: `${Number(point.expenses) / max * 100}%`}"/></div><small>{{ point.date.slice(8) }}</small></div></div><div v-if="max === 1" class="chart-empty">Birinchi savdongizdan keyin grafik shakllanadi</div></div><footer class="chart-footer"><span><Info :size="14"/>Faqat tizimga kiritilgan ma’lumotlar</span><RouterLink to="/orders">Buyurtmalar <ArrowRight :size="15"/></RouterLink></footer></section><section class="panel"><header class="panel-heading"><div><h2>Xarajatlar tarkibi</h2><p>Pul nimaga sarflandi?</p></div><RouterLink to="/expenses" class="icon-button" aria-label="Xarajatlarni ochish"><ArrowUpRight :size="20"/></RouterLink></header><div class="expense-total">{{ money(data.expenses) }} <small>so‘m</small></div><div v-if="!data.expense_categories.length" class="empty-state compact"><Wallet :size="36" :stroke-width="1.3"/><strong>Hali xarajat kiritilmagan</strong><span>Yangi xarajat shu yerda aks etadi.</span><RouterLink to="/expenses" class="text-link">Xarajat qo‘shish →</RouterLink></div><RouterLink v-for="(item,index) in data.expense_categories" :key="item.category" to="/expenses" class="expense-category"><div><span><i :style="{background: ['#22795f','#d6aa6a','#8fae9f','#8e99bd'][index % 4]}"/>{{ item.category }}</span><strong>{{ money(item.total) }}</strong></div><div class="progress-track"><span :style="{width: `${Number(item.total) / totalExpense * 100}%`}"/></div></RouterLink></section></div><div class="dashboard-bottom"><section class="panel"><header class="panel-heading"><div><h2>So‘nggi buyurtmalar</h2><p>Kassadagi oxirgi harakatlar</p></div><RouterLink to="/orders" class="text-link">Barchasi <ArrowRight :size="15"/></RouterLink></header><div class="table-wrap"><table><thead><tr><th>BUYURTMA</th><th>VAQT</th><th>SUMMA</th><th>HOLAT</th></tr></thead><tbody><tr v-for="order in data.recent_orders" :key="order.id"><td><strong>#{{ String(order.id).padStart(4,'0') }}</strong><small>{{ order.table ? `${order.table}-stol` : 'Tezkor savdo' }}</small></td><td>{{ dateLabel(order.created_at) }}</td><td class="number">{{ money(order.total) }}</td><td><span class="status" :class="order.status">{{ order.status === 'paid' ? 'To‘langan' : 'Ochiq hisob' }}</span></td></tr></tbody></table><div v-if="!data.recent_orders.length" class="empty-state compact">Buyurtmalar hali yo‘q. Kassadan birinchi buyurtmani kiriting.</div></div></section><section class="insight-card"><span class="insight-icon"><Package :size="23"/></span><span class="eyebrow">BUGUNGI NAZORAT</span><h2>Har bir mahsulot<br>hisobda bo‘lsin.</h2><p>{{ data.low_stock ? `${data.low_stock} ta mahsulot minimal qoldiqqa yetgan. Kirimni tekshiring.` : 'Kun oxirida haqiqiy sarfni kiritib, ombor qoldig‘ini yangilang.' }}</p><RouterLink to="/inventory" class="button">Omborni ko‘rish <ArrowUpRight :size="17"/></RouterLink></section></div><p class="data-note"><Info :size="15"/>{{ data.basis }} Yangilandi: {{ dateLabel(data.as_of) }}.</p></template></template>
